import {TextSelection,AllSelection} from '@tiptap/pm/state';
import {closeHistory} from '@tiptap/pm/history';
import {decodeDocumentFile,encodeDocumentFile} from '../src/redesign/document-store.mjs';
import {createEmptyManualDocument,validateManualDocument,copyManualDocument,migrateV1Document,isSafeManualAsset} from '../src/redesign/manual-v2.mjs';
import {createManualState,documentFromState,manualSchema,manualCommands as commands,insertManualBlock,findManualObject,updateManualObject,selectManualObject,duplicateManualObject,deleteManualObject,moveManualObject,appendManualStep,addManualTableRow,deleteManualTableRow,replaceManualSelection,addManualTableColumn,deleteManualTableColumn,setManualLink,manualFigureMediaSpec,manualCoverLogoSpec,ensureParagraphAfter,insertParagraphAtGap,getManualSlashTrigger,executeManualBlockCommand,normalizeManualPastedSlice,prepareManualClipboardAssets,rekeyManualPastedAssets} from '../src/redesign/manual-kernel.mjs';
function harness(document=createEmptyManualDocument()){
 let state=createManualState({document});const dispatch=tr=>state=state.applyTransaction(tr).state;
 return {get state(){return state;},get document(){return documentFromState(state);},dispatch,run:cmd=>cmd(state,dispatch),boundary:()=>dispatch(closeHistory(state.tr)),select:pos=>dispatch(state.tr.setSelection(TextSelection.create(state.doc,pos)))};
}
const ids=value=>{const result=[];const visit=v=>{if(!v||typeof v!=='object')return;if(v.id)result.push(v.id);for(const [k,c]of Object.entries(v))if(k!=='extensions'&&c&&typeof c==='object')Array.isArray(c)?c.forEach(visit):visit(c);};visit(value);return result;};
// Small DOM surface for the real PM parser; no browser or extra dependency.
function clipboardElement(tag,attributes={},nodes=[]){
 const dom={nodeType:1,nodeName:tag.toUpperCase(),tagName:tag.toUpperCase(),childNodes:nodes,style:{length:0},getAttribute:key=>attributes[key]??null,matches(selector){return selector.split(',').some(value=>{value=value.trim();const attr=/^(\w+)?\[([\w-]+)(?:="([^"]*)")?\]$/.exec(value);return attr?(!attr[1]||attr[1].toLowerCase()===tag)&&Object.hasOwn(attributes,attr[2])&&(attr[3]===undefined||attributes[attr[2]]===attr[3]):value.toLowerCase()===tag;});}};
 dom.firstChild=nodes[0]||null;dom.lastChild=nodes.at(-1)||null;nodes.forEach((node,index)=>{node.parentNode=dom;node.previousSibling=nodes[index-1]||null;node.nextSibling=nodes[index+1]||null;});return dom;
}
function clipboardDOM(node){
 if(node.isText)return {nodeType:3,nodeName:'#text',nodeValue:node.text};
 function render(spec){const hasAttrs=typeof spec[1]==='object'&&!Array.isArray(spec[1]);return clipboardElement(spec[0],hasAttrs?spec[1]:{},spec.slice(hasAttrs?2:1).flatMap(part=>part===0?Array.from({length:node.childCount},(_,index)=>clipboardDOM(node.child(index))):[Array.isArray(part)?render(part):{nodeType:3,nodeName:'#text',nodeValue:part}]));}
 return render(node.type.spec.toDOM(node));
}
function parseClipboardSlice(slice){return DOMParser.fromSchema(manualSchema).parseSlice(clipboardElement('div',{},Array.from({length:slice.content.childCount},(_,index)=>clipboardDOM(slice.content.child(index)))),{preserveWhitespace:true});}
test('empty draft round trips without optional field injection',()=>{const d=createEmptyManualDocument();assert.deepEqual(documentFromState(createManualState({document:d})),d);assert.equal(validateManualDocument(d),d);});
for(const file of ['compact.json','gallery.json','authoring-guide/manual.json'])test(`v1 ${file} explicit copy migrates and round trips all content`,async()=>{const source=JSON.parse(await readFile(new URL('../../../examples/'+file,import.meta.url),'utf8'));const before=structuredClone(source),result=migrateV1Document(source);assert.deepEqual(source,before);assert.deepEqual(result.source,source);assert.deepEqual(documentFromState(createManualState({document:result.document})),result.document);});
for(const type of ['paragraph','heading','list','procedure','figure','table','callout','quote','mediaGroup'])test(`${type} insertion is valid, unique, undoable`,()=>{const h=harness();h.run(selectManualObject(h.document.pages[0].blocks[0].id));const before=h.document;assert.equal(h.run(insertManualBlock(type)),true);const d=h.document;assert.equal(d.pages[0].blocks[1].type,type);assert.equal(new Set(ids(d)).size,ids(d).length);h.run(commands.undo);assert.deepEqual(h.document,before);h.run(commands.redo);assert.deepEqual(h.document,d);});
for(const kind of ['callout','quote','toggle','step'])test(`node-selected nested ${kind} paragraph inserts immediately after itself and undoes`,()=>{
 const p=text=>({id:crypto.randomUUID(),type:'paragraph',content:[{type:'text',text}]}),first=p('첫 문단'),second=p('둘째 문단'),outside=p('컨테이너 밖'),title=[{type:'text',text:'제목'}],body={id:crypto.randomUUID(),...(kind!=='step'?{type:kind}:{}),blocks:[first,second],...(kind==='quote'?{}:{title}),...(kind==='callout'?{tone:'cautionary'}:kind==='toggle'?{open:true}:{})};
 const container=kind==='step'?{id:crypto.randomUUID(),type:'procedure',start:1,steps:[body]}:body,d=createEmptyManualDocument();d.pages[0].blocks=[container,outside];const h=harness(d);h.run(selectManualObject(first.id,{text:false}));const before=h.state;h.boundary();assert.equal(h.run(insertManualBlock('paragraph')),true);
 const result=h.document,after=kind==='step'?result.pages[0].blocks[0].steps[0]:result.pages[0].blocks[0];assert.equal(result.pages[0].blocks.length,2);assert.equal(after.blocks.length,3);assert.deepEqual(after.blocks[0],first);assert.deepEqual(after.blocks[2],second);assert.deepEqual(after.blocks[1].content,[]);assert.deepEqual(result.pages[0].blocks[1],outside);assert.equal(h.state.selection.$from.parent.attrs.id,after.blocks[1].id);assert.equal(new Set(ids(result)).size,ids(result).length);
 h.run(commands.undo);assert.deepEqual(h.document,d);assert.ok(h.state.selection.eq(before.selection));
});
test('page creation and explicit deletion maintain at least one page',()=>{const h=harness(),original=h.document;assert.equal(h.run(deleteManualObject(original.pages[0].id)),false);h.run(insertManualBlock('page'));assert.equal(h.document.pages.length,2);const id=h.document.pages[1].id;h.boundary();h.run(deleteManualObject(id));assert.equal(h.document.pages.length,1);h.run(commands.undo);assert.equal(h.document.pages[1].id,id);});
for(const entry of ['selected page','page menu target','selected cover','cover menu target'])test(`new page follows the ${entry} instead of appending to the document, and one undo restores the original selection`,()=>{
 const afterCover=entry.includes('cover'),menuTarget=entry.endsWith('menu target'),d=createEmptyManualDocument();d.pages.push(createEmptyManualDocument().pages[0],createEmptyManualDocument().pages[0]);d.pages.forEach((page,index)=>{page.title=[{type:'text',text:`페이지 ${index+1}`}];page.extensions={keep:index};page.blocks[0].content=[{type:'text',text:`본문 ${index+1}`,marks:[{type:'strong'}]}];});if(afterCover)d.cover={id:crypto.randomUUID(),title:[{type:'text',text:'표지'}],metadata:[],blocks:[],extensions:{keep:'cover'}};const h=harness(d),targetId=afterCover?d.cover.id:d.pages[0].id;
 h.run(selectManualObject(menuTarget?d.pages[2].blocks[0].id:targetId,{text:menuTarget}));h.boundary();const before=h.state,beforeDocument=h.document,command=menuTarget?executeManualBlockCommand('page',{targetId,mode:'insert',attrs:{title:'새 페이지'}}):insertManualBlock('page',{title:'새 페이지'});assert.equal(command(h.state),true);assert.equal(h.state,before);assert.equal(command(h.state,h.dispatch,{composing:true}),false);assert.equal(h.state,before);assert.equal(h.run(command),true);
 const after=h.document,added=after.pages[afterCover?0:1];assert.deepEqual(after.pages.filter(page=>page.id!==added.id),beforeDocument.pages);assert.deepEqual(after.cover,beforeDocument.cover);assert.deepEqual(added.title,[{type:'text',text:'새 페이지'}]);assert.equal(added.blocks.length,1);assert.deepEqual(added.blocks[0].content,[]);assert.equal(new Set(ids(after)).size,ids(after).length);assert.equal(h.state.selection.$from.parent.type.name,'pageTitle');assert.equal(h.state.selection.$from.node(1).attrs.id,added.id);const afterSelection=h.state.selection;
 h.run(commands.undo);assert.deepEqual(h.document,beforeDocument);assert.ok(h.state.selection.eq(before.selection));h.run(commands.redo);assert.deepEqual(h.document,after);assert.ok(h.state.selection.eq(afterSelection));
});
test('typing Enter splits paragraphs and gives distinct IDs restored by undo',()=>{const h=harness(),id=h.document.pages[0].blocks[0].id;h.run(selectManualObject(id));h.dispatch(h.state.tr.insertText('첫째😀둘째'));h.boundary();h.select(findManualObject(h.state,id).pos+3);assert.equal(h.run(commands.enter),true);assert.equal(h.document.pages[0].blocks.length,2);assert.equal(new Set(ids(h.document)).size,ids(h.document).length);h.run(commands.undo);assert.equal(h.document.pages[0].blocks.length,1);assert.equal(h.document.pages[0].blocks[0].id,id);});
