test('object metadata edits preserve extension fields and undo',()=>{const d=createEmptyManualDocument();d.pages[0].extensions={vendor:{flag:true}};const h=harness(d);h.run(updateManualObject(d.id,{title:'문서'}));assert.equal(h.document.title,'문서');assert.deepEqual(h.document.pages[0].extensions,d.pages[0].extensions);h.run(commands.undo);assert.deepEqual(h.document,d);});
test('duplicate renews descendant IDs, move preserves them, undo restores',()=>{const h=harness();h.run(selectManualObject(h.document.pages[0].blocks[0].id));h.run(insertManualBlock('procedure'));const id=h.document.pages[0].blocks[1].id;h.boundary();h.run(duplicateManualObject(id));const duplicated=h.document.pages[0].blocks[2];assert.equal(new Set(ids(h.document)).size,ids(h.document).length);h.boundary();h.run(moveManualObject(duplicated.id,{direction:'up'}));assert.equal(h.document.pages[0].blocks[1].id,duplicated.id);h.run(commands.undo);assert.equal(h.document.pages[0].blocks[2].id,duplicated.id);});
