test('invalid IDs, links, crop, asset names and unknown nodes reject without mutation',()=>{const d=createEmptyManualDocument();for(const modify of [v=>v.pages[0].id=v.id,v=>v.pages[0].blocks[0].content=[{type:'text',text:'x',marks:[{type:'link',href:'javascript:bad'}]}],v=>v.pages[0].blocks[0].type='unknown']){const bad=structuredClone(d);modify(bad);assert.throws(()=>validateManualDocument(bad));}for(const name of ['../x','/x','a\\b','a//b','a/./b','data:x','a\u0000b'])assert.equal(isSafeManualAsset(name),false);assert.equal(isSafeManualAsset('assets/x.png'),true);});
