 d.pages[0].blocks[0].content=[{type:'text',text:'ABC'}];second.blocks[0].content=[{type:'text',text:'DEF'}];
 const h=harness(d),firstPos=findManualObject(h.state,d.pages[0].blocks[0].id).pos+2,lastPos=findManualObject(h.state,second.blocks[0].id).pos+2;
 h.dispatch(h.state.tr.setSelection(TextSelection.create(h.state.doc,firstPos,lastPos)));const before=h.state;
 assert.equal(h.run(replaceManualSelection('X')),true);assert.deepEqual(h.document.pages.map(p=>p.id),d.pages.map(p=>p.id));
 assert.equal(h.document.pages[0].blocks[0].content[0].text,'AX');assert.equal(h.document.pages[1].blocks[0].content[0].text,'EF');
