for(const href of ['https://new.invalid',null])test(`caret link edit ${href??'remove'} updates entire same-link extent and undoes`,()=>{
 const d=createEmptyManualDocument(),link={type:'link',href:'https://old.invalid'};
 d.pages[0].blocks[0].content=[{type:'text',text:'before '},{type:'text',text:'one',marks:[link]},{type:'text',text:'two',marks:[{type:'strong'},link]},{type:'text',text:'three',marks:[link]},{type:'text',text:'different',marks:[{type:'link',href:'https://different.invalid'}]},{type:'text',text:' after'}];
 const h=harness(d),pos=findManualObject(h.state,d.pages[0].blocks[0].id).pos+1;h.select(pos+11);const before=h.state;
 assert.equal(setManualLink(href)(h.state),true);assert.equal(h.state,before);assert.equal(h.run(setManualLink(href)),true);
 const runs=h.document.pages[0].blocks[0].content;
 const links=runs.flatMap(run=>(run.marks||[]).filter(m=>m.type==='link').map(m=>m.href));assert.equal(links.includes(link.href),false);assert.ok(links.includes('https://different.invalid'));
 assert.ok(runs.some(run=>run.text==='two'&&run.marks.some(m=>m.type==='strong')));if(href)assert.equal(links.filter(v=>v===href).length,3);
 assert.equal(h.state.selection.from,before.selection.from);h.run(commands.undo);assert.ok(h.state.doc.eq(before.doc));assert.ok(h.state.selection.eq(before.selection));
});
